BEGIN;
SELECT plan(28);
SELECT has_table('public', 'stores', 'store registry exists');
SELECT has_table('public', 'customers', 'normalized CRM table exists');
SELECT has_table('public', 'order_items', 'normalized order items table exists');
SELECT has_column('public', 'categories', 'store_key', 'categories are store scoped');
SELECT has_column('public', 'products', 'store_key', 'products are store scoped');
SELECT has_column('public', 'coupons', 'store_key', 'coupons are store scoped');
SELECT has_column('public', 'curated_phrases', 'store_key', 'phrases are store scoped');
SELECT has_column('public', 'user_roles', 'store_key', 'roles are store scoped');
SELECT has_column('public', 'orders', 'customer_id', 'orders link to normalized customers');
SELECT ok((SELECT relrowsecurity FROM pg_class WHERE oid = 'public.orders'::regclass), 'orders keep RLS enabled');
SELECT ok((SELECT relrowsecurity FROM pg_class WHERE oid = 'public.customers'::regclass), 'customer PII keeps RLS enabled');
SELECT ok((SELECT relrowsecurity FROM pg_class WHERE oid = 'public.order_items'::regclass), 'order items keep RLS enabled');
SELECT ok(NOT has_table_privilege('anon', 'public.customers', 'SELECT'), 'anonymous users cannot read customer records');
SELECT ok(NOT has_table_privilege('anon', 'public.orders', 'SELECT'), 'anonymous users cannot read orders');
SELECT ok(NOT has_table_privilege('anon', 'public.order_items', 'SELECT'), 'anonymous users cannot read order items');
SELECT ok(EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='categories' AND policyname='Categorias públicas anon' AND qual ILIKE '%papelemi%'), 'public category policy is scoped to PapeLemi');
SELECT ok(EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='products' AND policyname='Produtos publicados anon' AND qual ILIKE '%papelemi%'), 'public product policy is scoped to PapeLemi');
SELECT ok(to_regprocedure('public.has_store_role(uuid,public.app_role,text)') IS NOT NULL, 'store-specific role check exists');
SELECT ok(EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='public.categories'::regclass AND conname='categories_pkey' AND contype='p' AND pg_get_constraintdef(oid) ILIKE '%store_key, slug%'), 'category PK includes store scope');
SELECT ok(EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='public.products'::regclass AND conname='products_pkey' AND contype='p' AND pg_get_constraintdef(oid) ILIKE '%store_key, slug%'), 'product PK includes store scope');
SELECT ok(EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='public.orders'::regclass AND conname='orders_store_key_id_key'), 'orders expose a store-scoped composite reference');
SELECT ok(EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='public.order_items'::regclass AND conname='order_items_store_order_fkey'), 'order items reference orders within the same store');
SELECT ok(EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='public.customers'::regclass AND conname='customers_store_email_unique'), 'customer email uniqueness is store scoped');
SELECT ok(EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='public.user_roles'::regclass AND conname='user_roles_store_user_role_key'), 'user roles are unique per store');
SELECT ok(to_regclass('public.products_store_category_idx') IS NOT NULL,'product store/category foreign key is indexed');
SELECT ok(to_regclass('public.user_roles_user_id_idx') IS NOT NULL,'user role user_id foreign key is indexed');
SELECT ok(to_regclass('public.products_store_category_idx') IS NOT NULL,'product store/category foreign key is indexed');
SELECT ok(to_regclass('public.user_roles_user_id_idx') IS NOT NULL,'user role user_id foreign key is indexed');
SELECT * FROM finish();
ROLLBACK;
